import{_ as t,o as s,c as a,a6 as i}from"./chunks/framework.CCKCzdWs.js";const u=JSON.parse('{"title":"DeepSeek CLI","description":"Use the official DeepSeek Harness command line tool for Piwi diagnosis and the assistant, with private profiles and scoped read-only MCP access.","frontmatter":{"title":"DeepSeek CLI","description":"Use the official DeepSeek Harness command line tool for Piwi diagnosis and the assistant, with private profiles and scoped read-only MCP access.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/deepseek-cli.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/deepseek-cli.html"}],["meta",{"property":"og:title","content":"DeepSeek CLI | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Use the official DeepSeek Harness command line tool for Piwi diagnosis and the assistant, with private profiles and scoped read-only MCP access."}]]},"headers":[],"relativePath":"guide/deepseek-cli.md","filePath":"guide/deepseek-cli.md","lastUpdated":1793447101000}'),n={name:"guide/deepseek-cli.md"};function o(r,e,d,l,c,p){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="deepseek-cli" tabindex="-1">DeepSeek CLI <a class="header-anchor" href="#deepseek-cli" aria-label="Permalink to &quot;DeepSeek CLI&quot;">​</a></h1><p>Piwi uses the official <a href="https://github.com/deepseek-ai/deepseek-harness" target="_blank" rel="noreferrer">DeepSeek Harness</a> command line tool, <code>dsh</code>. It runs diagnosis, research and assistant roles using your DeepSeek credentials. No OpenAI API key is used.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><p>Install the supported official developer-preview release on the machine running Piwi:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @deepseek-ai/dsh@0.2.1-rc.2</span></span></code></pre></div><p>Sign in through <code>dsh web</code>, or configure <code>DEEPSEEK_API_KEY</code> for that machine. Piwi reads the DeepSeek account grant or saved DeepSeek API-key reference from <code>DSH_HOME/.credentials.yaml</code> (default: <code>.dsh/.credentials.yaml</code> in your home directory). A saved account takes precedence; a saved API key takes precedence over the environment key. Other provider credentials and <code>.env</code> files are excluded.</p><p>Select <strong>DeepSeek Harness</strong> under <strong>Command-line tools</strong> in <strong>Settings → AI</strong>. The desktop app discovers <code>dsh</code> on PATH; servers opt in by setting <code>PIWI_DEEPSEEK_CLI_PATH</code> to its absolute launcher path. Use <code>PIWI_AI_PROVIDER=deepseek-cli</code> for environment-managed configuration. No API key is stored in Piwi for this provider. <strong>Recheck</strong> reports installation compatibility and local credential presence; credential validity is checked when a model is called. Sign-in and sign-out remain in Harness.</p><p>The integration targets <code>0.2.1-rc.2</code>. Harness is in developer preview, so Piwi refuses other versions until their profile and event contracts have been verified.</p><h2 id="models-and-output" tabindex="-1">Models and output <a class="header-anchor" href="#models-and-output" aria-label="Permalink to &quot;Models and output&quot;">​</a></h2><p>Blank model fields use <code>deepseek-flash</code>; enter another model ID supported by your DeepSeek account or API access. Embeddings need an OpenAI-compatible provider. CLI diagnosis sends text evidence and omits image attachments.</p><p>The official CLI emits JSONL messages, per-step usage and a final answer. Text streams in completed-message chunks. Piwi adds cache reads and writes to uncached input tokens for its total input count, and reports the cache counts separately. Missing usage stays unknown. Dollar cost is unknown because the CLI does not report it.</p><p>JSON Schema requests are included in the system instructions. Harness has no native JSON Schema output flag in this release, so schema-conforming output depends on the model; this is not a strict structured-output guarantee. Intermediate commentary is excluded from the returned structured answer.</p><h2 id="isolation" tabindex="-1">Isolation <a class="header-anchor" href="#isolation" aria-label="Permalink to &quot;Isolation&quot;">​</a></h2><p>Each run uses a private temporary home, working directory and generated profile with no inherited bundles. The profile contains only official model and agent plugins, with the turn&#39;s Piwi MCP client added for assistant runs. Shell, filesystem, web, skill, plugin-management and project-instruction plugins are absent. User profiles, plugins, endpoint overrides, runtime injection variables and unrelated credentials are excluded.</p><p>Only the selected DeepSeek credential is copied. The assistant&#39;s MCP token stays in a private profile file, outside the command line. The existing turn endpoint enforces the asking user&#39;s project scope, read-only tools and answer limits; the token is revoked when the turn ends. Processes are killed at the turn timeout, and temporary files are removed.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/ai-provider.html">AI provider</a></li><li><a href="/guide/codex-cli.html">Codex CLI</a></li><li><a href="/features/assistant.html">Assistant</a></li></ul>',17)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
